from pathlib import Path
import json,html,re,shutil
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'data'
sources=json.loads((D/'sources.json').read_text());people=json.loads((D/'people.json').read_text());recs=json.loads((D/'recordings.json').read_text());sd={s['id']:s for s in sources};pd={p['id']:p for p in people}
def esc(x):return html.escape(str(x),quote=True)
def cite(*ids,loc=None):
 return '<span class="citations">'+''.join(f'<a class="cite" href="sources.html#{esc(i)}" title="{esc(sd[i]["title"])}">{esc(sd[i]["title"])}</a>' for i in ids)+(f'<span class="locator">{esc(loc)}</span>' if loc else '')+'</span>'
def p(text,*refs,loc=None):return f'<p>{text}{cite(*refs,loc=loc) if refs else ""}</p>'
def badge(status):return f'<span class="badge {"inferred" if status in ["Strong identification","Unverified lead","Unresolved"] else "oral" if "testimony" in status.lower() or status=="Family history" else "documented"}">{esc(status)}</span>'
def img(name,alt,caption='',source=None,cls=''):
 return f'<figure class="{cls}"><a href="assets/documents/{esc(name)}"><img src="assets/images/{esc(Path(name).stem)}.jpg" alt="{esc(alt)}" loading="lazy" width="1200" height="820"></a><figcaption>{caption}{cite(source) if source else ""}</figcaption></figure>'
def head(kicker,title,dek):return f'<header class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="dek">{dek}</p></header>'
def section(title,content,id=None):return f'<section{f" id={esc(id)}" if id else ""}><h2>{title}</h2>{content}</section>'
def callout(title,text):return f'<aside class="callout"><h3>{title}</h3>{text}</aside>'
nav=[('gilinsky.html','The Gilinsky family'),('branch.html','The Opalin story'),('tree.html','Family tree'),('people.html','People'),('timeline.html','Timeline'),('archive.html','Archive'),('sources.html','Sources')]
def page(filename,title,content,active=None):
 n=''.join(f'<a href="{f}" {"aria-current=page" if f==(active or filename) else ""}>{label}</a>' for f,label in nav)
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A sourced family history: Gilinsky, Milstein, Lederer, Appelbaum, Alter and Slot. Documents, voices and journeys from Opalin to southern Africa."><meta name="theme-color" content="#294A63"><title>{esc(title)} · Our Family Archive</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="index.html"><img class="brand-mark" src="assets/bytejam-logo.svg" width="40" height="40" alt="" aria-hidden="true"><span>Our Family Archive<small>Stories, voices &amp; evidence</small></span></a><button class="nav-toggle" aria-expanded="false" aria-controls="main-nav">Menu</button><nav id="main-nav" aria-label="Main navigation">{n}</nav></header><main id="main">{content}</main><footer class="site-footer"><div><a class="footer-brand" href="index.html"><img src="assets/bytejam-logo.svg" width="32" height="32" alt="" aria-hidden="true">Our Family Archive</a><p>A history assembled from documents and remembered lives.</p></div><div><a href="places.html">Places &amp; journeys</a><a href="voices.html">Listen to the recordings</a><a href="research.html">Open questions</a><a href="about.html">About this archive</a></div><p class="colophon">Research edition · 20 November 2026<br>Family material collected by Mark Cohen. Earlier history by Ethan Cohen.<br><a href="data/asset-register.json">File provenance register</a></p></footer><dialog id="image-dialog"><button class="dialog-close" autofocus aria-label="Close image">Close</button><img alt=""><p></p></dialog><noscript><style>.site-header nav{{display:flex;flex-wrap:wrap}}.nav-toggle{{display:none}}</style><p class="noscript">All history and source links are readable without JavaScript. Search, filters and image enlargement need JavaScript.</p></noscript></body></html>'''
 (ROOT/filename).write_text(out)
chapters=[
 ('opalin.html','Before the journey','Life in Opalin','School photographs, a market square, the river and the remembered world of home.','opalin-school.jpg'),
 ('journey.html','Across Europe &amp; the sea','The journey of 1934','A passport and passenger list trace Doba’s journey with three children.','doba-passport-family.jpg'),
 ('johannesburg.html','A new home','Life in southern Africa','Moshe’s death, Doba’s resourcefulness, Arke and the later Slot household.','riva-max-mark-wedding.jpg'),
 ('lederer.html','The maternal family','The Lederer connections','Hela, the Warsaw baker, three sisters and an aunt in Denver.','warsaw-directory-page.jpg'),
 ('alter.html','Across the Bug, then to Israel','The Alter connection','A memoir and a recorded family account connect the branches.','chaya-alter-testimony.jpg'),
 ('remembrance.html','Those who remained','Opalin and the Holocaust','The killing-site research, individual testimonies and what remains unknown.','nutke-from-ethan-0.jpg')]
def chaptercards():return '<div class="chapter-grid">'+''.join(f'<a class="chapter-card" href="{f}"><div class="chapter-image"><img src="assets/images/{im}" alt="" loading="lazy"></div><div><p class="eyebrow">{ey}</p><h3>{t}</h3><p>{d}</p></div></a>' for f,ey,t,d,im in chapters)+'</div>'
content='''<section class="home-hero"><div class="hero-copy"><p class="eyebrow">The stories that brought us here</p><h1>Many branches.<br>One unfolding<br><em>family story.</em></h1><p class="dek">An archive of the people, places and journeys that shaped our family—told through photographs, original documents and the voices of those who remembered.</p><a class="button" href="branch.html">Explore the Opalin branch</a><a class="text-link" href="about.html">How to read this archive</a></div><figure class="hero-image"><img src="assets/images/opalin-school.jpg" alt="Children and teachers posed outside a wooden school building in Opalin"><figcaption>Opalin, before the journey. A family school photograph; date unknown.</figcaption></figure><span class="hero-caption" aria-hidden="true">Remembered lives / preserved evidence</span></section>'''
branches=json.loads((D/'branches.json').read_text())
content+='<section class="branch-section"><div class="section-intro"><p class="eyebrow">Explore by branch</p><h2>Every family line has<br>its own beginning.</h2><p>Explore the Milstein and Lederer families of Opalin and the Gilinsky family of Benoni, Upington and Johannesburg. Each branch shares the people, places and source library.</p></div>'
for branch in branches:
 content+=f'<a class="branch-feature" href="{esc(branch["page"])}"><span class="branch-tag">{esc(branch.get("status","Family collection"))}</span><h3>{esc(branch["title"])}</h3><p>{esc(" · ".join(branch.get("places",[])))}</p><span class="branch-foot">{esc(branch.get("description","Documents, family voices and a working tree"))}</span></a>'
content+='<div class="future-branch"><span class="branch-tag">Room to grow</span><h3>More branches,<br>when their stories<br>are ready.</h3><p>Future collections can share the same people, places and source library.</p></div></section>'
content+=section('Start with a story',chaptercards())
content+='<section class="archive-band"><div><p class="eyebrow">A family archive, with evidence</p><h2>The document behind the story.</h2><p>Follow a citation to the source, inspect a saved image, or hear the recording. Where memories and records disagree, the difference stays visible.</p><a class="button light" href="sources.html">Browse the source library</a></div><img src="assets/images/doba-passport-family.jpg" alt="Doba’s passport with her photograph and three children"></section>'
page('index.html','Home',content)
content=head('Milstein &amp; Lederer / The Opalin collection','From Opalin,<br>across generations.','A family story carried from a small town in Volhynia to southern Africa and Israel, preserved in passports, photographs and recorded memories.')
content+='<div class="branch-toolbar"><a href="tree.html">Explore the tree</a><a href="timeline.html">Follow the timeline</a><a href="voices.html">Hear the family</a><a href="research.html">See the open questions</a></div>'
content+=img('doba-passport-family.jpg','Doba and three children in the passport','Doba with Rywka, Szul-Beniamin and Pinchas. The passport identifies Opalin as her birthplace.','passport','wide-photo')
content+='<div class="reading-width">'+p('The central household is <a href="people.html#moshe">Moshe Milstein</a> and <a href="people.html#doba">Doba Lederer</a>, and their children Aron (Arke), Riva (Masie), Ben (Saul) and Philip (Pinchas). Moshe and Arke went ahead; Doba’s passport and the 1934 manifest record her travelling with the three younger children.','ben1','passport','manifest',loc='Uncle Ben – 1, 04:24–05:35')+p('The family’s recollections reach beyond that household: Minnie tells of the Milsteins and Appelbaums; Hela recalls her Lederer childhood and Warsaw uncle; Israel Alter’s memoir helps connect the family across the Bug and onward to Israel. These connections vary in evidential strength.','minnie1','minnie2','hela2','alter-memoir')+'</div>'
content+=chaptercards()
content+=section('Read the evidence in its own terms','<div class="three-up"><article>'+badge('Documented')+'<h3>What a source says</h3><p>A date or name is legible in an inspected document. This does not automatically prove the person is our relative.</p></article><article>'+badge('Family testimony')+'<h3>What the family remembers</h3><p>Recollections carry experience, detail and relationships. Dates and names can shift across tellings.</p></article><article>'+badge('Strong identification')+'<h3>What the evidence suggests</h3><p>Matching records and testimony form a reasoned connection. Remaining gaps are stated alongside it.</p></article></div>')
page('branch.html','The Opalin branch',content)
# Full chapter narratives, with claim-adjacent references.
content=head('The Opalin story / Before the journey','A remembered home<br>beside the Bug.','Schoolchildren, a market square and the routines of a Jewish household: the family tapes preserve a place through the texture of everyday life.')
content+=img('opalin-school.png','Class photograph outside an Opalin school','Mark thinks Riva is in the front row, second from the right, holding flowers. Identification remains tentative.','school','wide-photo')
content+='<div class="story-layout"><aside class="story-aside"><p class="eyebrow">Place names</p><h3>Opalin / Vyshnivka</h3><p>The researched town is in Volyn, Ukraine. Ruda Opalin is a separate locality across the border.</p><a href="places.html">See places &amp; journeys</a></aside><div class="prose">'
content+=section('Locating Opalin',p('Yahad–In Unum identifies its killing-site entry as Vyshnivka, formerly Opalin, in Volyn, Ukraine. This supports the location identified in Ethan’s earlier family history. Similar names in Poland, including Ruda Opalin, should not be treated as interchangeable.','yahad','ethan')+p('Doba’s Polish passport gives Opalin as both birthplace and residence. Ethan’s early history places the family there in interwar Poland; the current location lies in Ukraine. The family’s documentary place name remains Opalin.','passport','passport-title','ethan'))
content+=section('The house, river and market',p('In the group conversation, childhood unfolds around a wood-fired stove and heated wall, washing clothes by the river, shopping for fish and kosher meat, and sleeping near the kitchen stove. A monthly market and market-square shops recur in the recollections. These are oral descriptions, not a reconstructed town plan.','opalin1',loc='01:03–04:10; 14:47–16:56; 27:11–27:41; 31:26–32:18')+p('Doba baked challah, with local non-Jewish teachers remembered among her customers. Hela describes gardens and potatoes, a beth midrash and two shtiblach, and her widowed mother’s tobacco, rolling-paper and match sales. Her estimate of 250 Jewish families is a recollection, not a census.','opalin1','hela2',loc='Opalin – 1, 14:12–14:40; Hela – 2, 00:26–00:49, 02:47–04:47'))
content+=section('School and learning',p('The school photograph survives because the family kept it. Ethan’s history also reproduces additional school groups and says Riva preserved schoolwork in Polish. The positions he identifies are family identifications; no school register has yet been matched to them.','school','ethan',loc='Ethan’s history, pp.6–7')+p('The tapes describe barefoot schoolchildren, a grandfather teaching in a cheder and hand-drawn school maps remembered within the family. The grandfather’s exact identity and the present location of the maps still need checking.','opalin1','ben1',loc='Opalin – 1, 05:00–05:32, 14:47–16:56, 18:32–19:12'))
content+=section('The wider family economy',p('Minnie’s account of the maternal Appelbaum family includes a watermill, ferry, farmland and an inn in or near a village transcribed Wulka or Volka. Many places share those names. The village is not securely mapped, and the businesses should not all be assigned to one person.','minnie1','minnie2',loc='Minnie – 1, 07:12–09:51; Minnie – 2, 28:32–29:58, 36:34–40:23')+p('Stories about the ferry and Chełm appear in the group recordings too, alongside humorous Chełm tales. Folklore is part of what the family shared; it is not treated here as a record of a particular historical event.','opalin1',loc='07:45–12:35'))
content+='</div></div>'
content+=section('More photographs from school',p('Mark supplied these two additional scans and confirms that Riva appears in both. Her position has not been specified for these scans; the dates, school name and identities of the other pupils and adults remain open. The original supplied scans are preserved separately from any smaller reproductions in Ethan’s earlier history.','school-scan-14','school-scan-12')+img('opalin-school-scan-14.jpg','Opalin school group, Scan 14; Riva is present according to Mark Cohen','Riva appears in this group, identified by Mark Cohen. Exact position and date unspecified.','school-scan-14')+img('opalin-school-scan-12.jpg','Opalin school group, Scan 12; Riva is present according to Mark Cohen','Riva appears in this group, identified by Mark Cohen. Exact position and date unspecified.','school-scan-12'))
page('opalin.html','Life in Opalin',content,'branch.html')
content=head('The Opalin story / 1934','A passport.<br>Three children.<br>A journey out.','The strongest route evidence is a sequence of documents. Recollections fill in the experience, while the stamps and manifest anchor the dates.')
content+='<div class="story-layout"><aside class="story-aside"><p class="eyebrow">The travelling party</p><h3>Doba, Rywka,<br>Szul &amp; Pinchas</h3><p>Moshe and Arke travelled separately.</p><a href="timeline.html">Open the full timeline</a></aside><div class="prose">'
content+=section('Moshe and Arke went first',p('Minnie recalls Moshe leaving around 1929, several years before Doba. Ben identifies Arke as the eldest brother and says he travelled ahead of the three younger children. Their own passenger lists have not been located. The 1934 manifest must not be used as evidence of Moshe’s voyage.','minnie1','ben1',loc='Minnie – 1, 23:06–24:23; Ben – 1, 04:24–05:35')+p('Ben remembers Brazil as the first intended destination and says grandfather Leibish suggested South Africa when visas could not be secured. Minnie names Stillman and Kirshner among Moshe’s fellow emigrants and a person sounding like Biederman who helped arrange papers. Spellings and details remain leads.','ben1','minnie1','minnie2',loc='Ben – 1, 20:00–22:00; Minnie – 1, 39:40–44:43; Minnie – 2, 13:09–15:30'))
content+=section('The European paper trail','<ol class="document-sequence"><li><strong>21 August 1934 · Warsaw</strong>'+p('South African settlement visa issued at the British Passport Office.','visa')+'</li><li><strong>1 September · Warsaw</strong>'+p('Emigration inspector’s approval appears in the passport observations.','observations')+'</li><li><strong>3 September · Warsaw</strong>'+p('German transit visa allows passage through Germany.','transit')+'</li><li><strong>6 September · Zbąszyń</strong>'+p('Polish border-control departure stamp.','exit')+'</li><li><strong>13 September · London</strong>'+p('Gloucester Castle manifest names Doba and the three children, booked to land at Cape Town.','manifest')+'</li><li><strong>7 October · South Africa</strong>'+p('Riva’s identification card records Gloucester Castle with this date.','riva-id')+'</li></ol>')
content+=img('manifest-1934.jpg','Passenger manifest showing Doba and children','Family entry: Doba, Rywka, Szul and Pinchus. Reference BT27/1400.','manifest')
content+=section('What the children remembered',p('The recordings recall a horse-and-cart journey to a railway station, a stay with a Lederer uncle whose Warsaw bakery occupied a basement, and hospitality during a London stop. Recalled durations and sequences do not all agree; they are not used to overwrite the dated documents.','opalin1','ben1',loc='Opalin – 1, 20:13–27:07; Ben – 1, 34:20–39:59')+p('Riva’s seasickness and the train journey inland give the crossing a human scale. Ben remembers Moshe meeting their train near Johannesburg and names Germiston in the later interview. These scenes are family testimony, separate from the arrival entry.','opalin1','ben1','ben2',loc='Ben – 1, 41:00–42:00; Ben – 2, 00:00–01:30'))
content+=section('An age discrepancy we can now see',img('riva-id-1934-0.jpg','Rywka Milsztejn identification card with birth date 19 November 1919','Card extracted from Ethan’s PDF. It is labelled an identification card.','riva-id')+p('The card gives Riva’s birth as <strong>19 November 1919</strong>, and the manifest lists Rywka aged fourteen in September 1934. A 7 October 1934 arrival would still be before her fifteenth birthday. Mark’s remembered age of sixteen on arrival remains part of the family account, but conflicts with these two documents.','riva-id','manifest','mark'))
content+=callout('Corrections to the earlier written history',p('Ethan’s PDF tentatively read an adjoining September stamp as South African arrival, described the German visa as an exit permit, and called Riva’s identification card a passport. The London manifest rules out a 3 September South African arrival; the German form is for transit; the card’s own heading identifies its type. Moshe was already abroad, rather than travelling on Doba’s passport.','ethan','manifest','transit','riva-id','ben1'))
content+='</div></div>'
page('journey.html','The journey of 1934',content,'branch.html')
content=head('The Opalin story / A new home','Building a life<br>in southern Africa.','Arrival did not end the difficult years. The family accounts describe loss, work, care and the creation of a close household in Johannesburg.')
content+='<div class="reading-width prose">'
content+=section('Moshe’s death: a strong documentary candidate',img('moishe-milstein-portrait.jpg','Portrait of Moishe (Moshe) Milstein','Moishe (Moshe) Milstein, Doba’s husband and father of Arke, Riva, Ben and Philip. Portrait identified and supplied by Mark Cohen; date and place unknown.','moishe-portrait')+p('The family portrait shows Moishe (Moshe) Milstein, remembered by Minnie and Ben as dying after an ulcer operation, about a year after Doba and the children arrived in South Africa.','moishe-portrait','minnie1','ben1')+p('The original certificate for <strong>Morris Millstein</strong> records death at Johannesburg Hospital on <strong>5 September 1935</strong>, registration the following day, age forty-one, Poland-born, married and a vegetable hawker. His home address was 31 Bezuidenhout Street, Troyeville. The medical entry describes peptic-ulcer surgery followed by haemorrhage.','morris')+p('Minnie and Ben recall an ulcer operation and death about a year after Doba and the children arrived. The certificate’s timing and medical details fit, and the address later matches Mina Milstein’s marriage. The identification with Moshe is strong, but the certificate does not name Doba or his parents. A linked estate or family death notice would close that gap.','morris','mina-marriage','minnie1','ben1',loc='Minnie – 1, 26:12–28:58; Ben – 1, 45:00–47:00')+p('The Find a Grave memorial gives 6 September, but has no photograph or relatives. The civil record explicitly separates death on the fifth from registration on the sixth. Allegations or remembered doubts about the operation are not treated as findings of medical wrongdoing.','morris','morris-memorial','minnie1'))
content+=section('Doba kept the household together',p('The tapes describe Doba selling clothing and household provisions, obtaining stock on credit and declining an offer of orphanage assistance. Minnie says Doba later funded her passage, which she repaid while paying board and beginning dressmaking work. Troyeville, Mayfair and later Greenside/Emmarentia recur in the family’s geography. Street details and the exact order of moves still need checking.','minnie2','ben1','ben2',loc='Minnie – 2, 00:10–01:49, 05:07–07:35; Ben – 1, 07:56–09:04, 40:00–49:00')+p('The recent family conversation remembers Masie leaving school at fourteen to help her brothers finish. The supplied text does not safely identify the individual speaker or verify the school-leaving date. It nevertheless preserves how the family remembers her contribution.','recent','mark'))
content+=section('Arke: a name restored to the family story',p('Ben names the siblings in order: Arke/Aaron, Riva, himself and Philip. Minnie recalls the eldest son’s later care, a visit in Kensington and his death soon after Doba. Mark confirms Arke’s identity and recalls that younger relatives learned of him only much later.','ben1','minnie1','mark','recent',loc='Ben – 1, 04:24–05:35; Minnie – 1, 29:05–32:36')+p('The gravestone for Aron Milstein identifies his father as Moshe and gives <strong>19 February 1977</strong>. Doba’s recorded death is <strong>7 February</strong>: twelve days earlier. Approximate intervals of ten or eleven days in conversation should not replace the recorded dates.','aron-grave','burials')+p('No personal institutional file or diagnosis has been established. Selwyn Segal is a family suggestion. Its official history places its original home in Kensington from 1956, which is geographically compatible with Minnie’s recollection but cannot account for care beginning in the 1930s. Trips described as going to Krugersdorp may have been a cover story, as Mark cautions; they do not establish the home’s location.','selwyn','mark','recent','minnie1'))
content+=section('The Slot stepfamily',p('Ben identifies Isaac Slot as his stepfather and remembers an unmarried son Nick joining the household. Mark remembers Paul, Nick and a sister, and believes they were stepchildren. Isaac’s gravestone establishes <strong>26 July 1952</strong>, resolving the tapes’ debated death year. Bulawayo as his death place remains an oral lead.','ben2','opalin2','mark','isaac-grave')+p('Annie Slot’s 1941 death notice names an Isaac Slot, estate agent, and children Hayme (reading provisional), Paul and Leslie, born 16 May 1923. Ethan’s tree calls Leslie “Nick”, a useful fit that still needs a linking record. It also shows Helman C. and Hymie with the same 1917–1981 dates, possibly duplicate entries. No unnamed sister has yet been securely identified.','annie','ethan')+p('The original Gazette notice, now visually checked on page 104, gives Doba’s estate as <strong>2783/77</strong>; Isaac’s is <strong>TAB MHG 5056/52</strong>. Both full packets remain outstanding. Enquiries were sent with Mark’s approval, and the archive records that they are awaiting replies. No record request was sent to Yahad.','doba-estate','doba-film','isaac-estate','mark'))
content+=section('Minnie, Riva and the next generation',p('A strong 1937 marriage candidate names <strong>Mina Milstein</strong> and <strong>Elias Spitalnik</strong>, supporting Minnie’s Milstein maiden surname. Her gravestone gives Menucha daughter of Leib, died 2 August 1997. Mark now confirms George as her husband’s family-used name and supplies a photograph of the couple. The link between George and the candidate civil name Elias still needs corroboration.','mina-marriage','minnie-grave','minnie2','minnie-george')+img('minnie-george.jpg','Minnie and her husband George','Identified by Mark Cohen; date and place not established.','minnie-george')+p('Ethan’s history describes Riva and Max Gilinsky’s hospitality, Friday-night and festival meals, and Riva’s work in the Emmarentia synagogue’s Ladies Guild. He writes from his position as their great-grandson. His tree dates Max 1910–2000 and Riva 1919–2015; Max’s death on 3 June 2000 and Riva’s on 1 June 2015 are now corroborated by the burial register; see the <a href="gilinsky.html">Gilinsky branch</a>.','ethan')+p('Ben and Philip’s recordings describe engineering and steelwork. Candidate archive descriptions pair Benjamin and Philip in Milrich Engineering in the 1950s. Their case files have not been read; titles are not evidence of fault, merits or outcomes. Mark confirms that both brothers and their wives are now deceased, superseding the old tree’s “Living” labels.','ben1','ben2','business','mark'))
content+=img('riva-wedding.jpg','Riva on her wedding day','Identified by Mark Cohen. Wedding date and place have not been supplied.','riva-wedding')+img('riva-max-mark-wedding.jpg','Riva and Max at Mark Cohen’s wedding','Riva (Masie/Mazie) and Max (Mackie) at Mark’s wedding, identified by Mark Cohen.','riva-max-mark-wedding')
content+='</div>'
page('johannesburg.html','Life in southern Africa',content,'branch.html')
content=head('The Opalin story / Lederer connections','Hela, three sisters<br>and a Warsaw baker.','The oral history gives relationships; a directory, burial patronymic and Pages of Testimony begin to put names beside them.')
content+='<div class="reading-width prose">'
content+=section('Hela’s parents and sisters',p('Hela says her father was Doba’s brother and died around 1920, leaving her mother with three girls. Hela’s burial entry supplies the patronymic <strong>Chaya Rivka daughter of Binyomin</strong>. Taken together, these make Binyomin Lederer a strong identification for Doba’s brother.','hela2','burials',loc='Hela – 2, 03:25–04:25')+p('The Yosefa/Jospa testimony names husband Beniamin, parents Eliezer and Chaya, and Opalin residence. Its original lists <strong>three children</strong>. Freida and Chuma’s testimonies share parents Beniamin and Yosefa, and an aunt Berland as submitter. This closely fits Hela’s household, but none of these forms expressly names Hela as a sister.','yosefa','freida','chuma')+p('Freida is a strong candidate for Hela’s sister Frida. The other sister is transcribed Nechama in the recording, whereas the testimony says Chuma/Khuma; that identification remains possible rather than settled. Yosefa’s handwritten marital entry may read widow, unlike the index’s married; the reading remains provisional.','hela2','freida','chuma','yosefa'))
content+=section('Mendel’s bakery',p('Hela recalls moving to Warsaw in 1924, aged twelve, to live with her father’s brother Mendel. She helped in the household and bakery and attended evening school. The group tapes also recall staying with a Lederer uncle who had a basement bakery. A 1928 directory lists <strong>Mendel Lederer, Ogrodowa 24</strong>, among Warsaw bakers.','hela2','opalin1','directory',loc='Hela – 2, 06:26–08:30; Opalin – 1, 21:39–24:06')+img('warsaw-directory-page.png','1928 Warsaw directory page with bakery listings','Printed page 1918, not the year 1918. Mendel’s entry is in the third column.','directory')+'<div class="table-wrap"><table><caption>Two testimonies that must not be silently merged</caption><thead><tr><th>Field</th><th>335860</th><th>1118855</th></tr></thead><tbody><tr><th>Birth</th><td>1880, Opalin</td><td>1885, Opalin</td></tr><tr><th>Occupation</th><td>Baker</td><td>Merchant</td></tr><tr><th>Wife</th><td>Riva</td><td>Rivka Fuks</td></tr><tr><th>Death entry</th><td>Warsaw ghetto</td><td>Treblinka, 1942</td></tr><tr><th>Submitter</th><td>Doba Kam, sister-in-law</td><td>Menukha Il, relative</td></tr></tbody></table></div>'+cite('mendel-a','mendel-b')+p('The baker testimony fits especially well, but Doba Kam has not been identified as Doba Slot. The second form’s blank parent and child fields do not resolve the duplicate question. No named son in Argentina has yet been securely connected to Mendel.','mendel-a','mendel-b','opalin1','minnie2',loc='Opalin – 1, 22:21–23:35; Minnie – 2, 35:07–35:31'))
content+=section('An aunt in Denver and the Sosna family',p('Hela describes her mother’s sister Emma in Denver, whose husband delivered coal. Emma sent about five dollars a month and clothing after Hela’s father died. Her surname is tentatively transcribed “Ray”. This is a maternal aunt, not automatically a Lederer. American census, marriage and death records are the next focused route.','hela2',loc='04:50–06:20')+p('Minnie describes Doba’s sisters and a Sosna/Reuter connection. A testimony for Pesl Sosne/Sosna, born Lederer, names husband Asher and daughter Ana Roiter. That is a useful collateral match, but the exact relationship to Doba remains unproved.','minnie1','minnie2','pesl',loc='Minnie – 1, 37:45–39:38; Minnie – 2, 30:45–35:31'))
content+=section('Hela and Harry’s separate journey',p('Hela gives her birth as 1912 and Harry’s as 1904, both in Opalin. She recalls marrying in 1934, apparently 30 December, and daughter Phyllis’s birth on 9 October 1935. Harry left for South Africa in August or September 1936, then moved to Bulawayo in November 1937.','hela2',loc='12:30–14:10; 22:14–23:06; 26:13–29:27')+p('Hela and Phyllis followed in June 1938. She names Warwick Castle and gives 27 June; the exact event represented by that date awaits a manifest. Her later account describes Scott Street, flats called Glen Eagles and a move to Johannesburg around February 1978. These dates belong to Hela and Harry, not Moshe and Doba.','hela2','hela1',loc='Hela – 2, 37:02–42:00; Hela – 1, 03:30–04:50, 11:33–15:38')+p('The paired burial entries give Harry’s death as 22 January 1985 and Hela’s as 26 November 2004, in adjoining plots. Their shared surname does not establish a precise cousin relationship before marriage.','burials','hela2'))
content+='</div>'
page('lederer.html','The Lederer connections',content,'branch.html')
content=head('The Opalin story / The Alter connection','A cousin in Tel Aviv.<br>A link across the generations.','Mark’s memory of staying with Israel Alter in 1986 leads to a published memoir, a filmmaker’s interview and an older family relationship.')
content+='<div class="reading-width prose">'
content+=section('Identifying Israel',p('Mark remembers staying with Israel Alter in Tel Aviv in 1986 and identifies filmmaker Naftali Alter as his son. A 2020 interview identifies the filmmaker’s parents as <strong>Israel and Pnina</strong>; the Film Archive biography confirms Naftali’s professional identity and 1947 Tel Aviv birth.','mark','naftali-interview','naftali-bio')+p('In the Dorohusk memorial book, Yisrael Alter names his mother Chaya Dvora, describes arriving in Palestine in 1936 aged twenty and recounts a Warsaw policeman refusing to help an assaulted Jew. The distinctive episode, trade and origin strongly identify him with the filmmaker’s father. The son’s retelling is not a second independent eyewitness account.','alter-memoir','naftali-interview'))
content+=section('The Milstein link',img('chaya-alter-testimony.png','Yad Vashem Page of Testimony for Chaya Dwora Alter','Chaya Dwora, born Milshtein. Saved browser screenshot, not a full-resolution original.','chaya')+p('The testimony for <strong>Chaya Dwora Alter, born Milshtein</strong>, gives Opalin birth in 1882, parents Israel and Zissel, husband Naftali and Dorohusk residence. These details converge with Israel’s memoir and Minnie’s grandparents’ names.','chaya','alter-memoir','minnie1','minnie2')+p('Minnie places Israel’s mother among her father’s sisters and includes a first-cousin exchange. The automatic aunt-name reading is uncertain; a second automated pass did not resolve it. Together the sources make a strong case for Chaya Dwora as Leibish’s sister, while an unambiguous full-name relationship record or careful human tape review is still desirable.','minnie1','chaya','alter-memoir',loc='Minnie – 1, approximately 03:33–05:06')+callout('The resulting relationship',p('If the older sibling link is correct, Israel and Moshe were first cousins; Israel was Riva’s first cousin once removed; filmmaker Naftali and Riva were second cousins. The <a href="tree.html#alter">Alter tree view</a> marks the inferred older connection.','minnie1','chaya','alter-memoir','naftali-interview')))
content+=section('Two incidents, kept separate',p('Israel’s published Warsaw incident concerns a policeman’s refusal to assist a beaten Jew. Mark’s separate family account concerns a British soldier in Palestine responding with an antisemitic insult when Israel asked for a cigarette light. Mark says Israel thereafter refused to speak English and remembers that refusal during the 1986 stay. The British-soldier story has no independently verified date or document here.','alter-memoir','naftali-interview','mark')+p('The memoir names siblings Rachel, Mordechai, David and Pinchas, and surviving brothers Avraham and Alter, who arrived in Israel in 1962. Its return-visit chronology is internally inconsistent, and the interview mentions one surviving brother rather than two. Those discrepancies remain open. Same-name Naftali victim records have not been used to fill the grandfather’s identity.','alter-memoir','naftali-interview'))
content+='</div>'
page('alter.html','The Alter connection',content,'branch.html')
content=head('The Opalin story / Remembrance','Those who remained<br>in Opalin.','Historical evidence documents mass murder. Individual family fates require their own evidence, and unresolved details should remain visible.')
content+='<div class="reading-width prose">'
content+=section('The killing-site record',p('Yahad–In Unum dates the mass shooting at the Jewish cemetery to <strong>2 October 1942</strong>. Its profile reports <strong>582 Jewish victims</strong>, a German unit from Lyuboml and assistance by Ukrainian police. This documents the destruction of the Jewish community; the inspected source does not itself prove that the whole town was razed.','yahad'))
content+=section('What the witness clip adds',p('The six-minute clip, reference 1443U, was reviewed through its embedded English subtitles. The witness describes requisitioned grave diggers, including his father, and police escorting the victims. No relative is named in the subtitles. The claim about a single shooter is attributed to a friend and is not presented as the witness’s own observation.','yahad-video',loc='00:40; 02:56–03:32; 04:36')+'<div class="table-wrap"><table><caption>Discrepancies preserved in the research</caption><thead><tr><th>Question</th><th>Profile</th><th>Video 1443U</th></tr></thead><tbody><tr><th>Victim total</th><td>582</td><td>Witness estimates 860</td></tr><tr><th>Witness / age</th><td>Serhiy S., born 1929; references 1441/1442</td><td>Title says born 1934; speaker says he was ten</td></tr></tbody></table></div>'+cite('yahad','yahad-video')+p('The quoted profile witness and the clip cannot safely be assumed to be the same person. The age and numerical differences have not been reconciled. <a href="https://www.yahadmap.org/en/#village/vyshnivka-former-opalin-volyn-ukraine.328" target="_blank" rel="noopener">Watch on the source page</a>; the full video is linked rather than republished.','yahad','yahad-video'))
content+=section('Nutke’s individual fate remains unresolved',img('nutke-from-ethan-0.jpg','Family portrait of Nutke Milstein','Nutke is identified in the family history as Moshe’s brother and Riva’s uncle.','nutke-photo')+p('The family remembers Nutke as having been killed in the Holocaust. Neither a secure victim testimony nor a personal death date, spouse or formal name has yet been found. The town’s massacre date is not automatically his death date. A search expansion from Nutke to Nuta/Natan is a tool, not an identification.','ethan','minnie1','nutke-photo')+p('One incomplete Natan/Nute record names father Yosef and wife Feigele, which conflicts with this family’s remembered father Leibish. It was not attached. Minnie also names an Appelbaum uncle Nutke: he is a different relative.','minnie2','mark'))
content+=section('The other testimonies',p('The Opalin-linked testimonies for Freida, Chuma, Yosefa and Pesl preserve names and relationships that may join the family tree. Their exact family identifications remain qualified. Chaya Dwora’s testimony gives death in 1941, so that date must not be reassigned to Opalin’s 1942 massacre. Mendel’s conflicting testimony locations likewise remain unreconciled.','freida','chuma','yosefa','pesl','chaya','mendel-a','mendel-b'))
content+='</div>'
page('remembrance.html','Opalin and the Holocaust',content,'branch.html')
exec((ROOT/'tools/gilinsky.py').read_text())
