content+='<div class="filter-bar"><label class="search-label">Find a person<input type="search" data-search="people" placeholder="Name, nickname or family…"></label><label>Family group<select data-filter="people"><option value="">All groups</option>'+''.join(f'<option>{esc(g)}</option>' for g in sorted(set(p['group'] for p in people)))+'</select></label><p class="result-count" data-count="people" aria-live="polite"></p></div><div class="people-grid" data-list="people">'
for person in people:
 content+=f'<article class="person-card" id="{person["id"]}" data-item data-group="{esc(person["group"])}" data-search-text="{esc(person["name"]+" "+person["aliases"]+" "+person["group"]+" "+person["summary"])}"><div class="person-meta"><span>{esc(person["group"])}</span>{badge(person["status"])}</div><h2>{esc(person["name"])}</h2><p class="aliases">{esc(person["aliases"])}</p><p class="dates">{esc(person["dates"])}</p><p>{person["summary"]}</p>'+(('<ul>'+''.join('<li>'+esc(f)+'</li>' for f in person['facts'])+'</ul>') if person['facts'] else '')+(f'<figure class="profile-photo"><a href="assets/documents/{esc(person["photo"])}"><img src="assets/images/{esc(person["photo"])}" alt="{esc(person["name"])}; family photograph supplied by Mark Cohen" loading="lazy"></a><figcaption>Family photograph, identified by Mark Cohen.{cite(person["photoSource"])}</figcaption></figure>' if person.get('photo') else '')+cite(*person['refs'])+'</article>'
content+='</div><p class="empty-state" data-empty="people" hidden>No people match this search. Try another spelling or clear the family filter.</p>'
page('people.html','People',content)
