content=head('The evidence / Source library','Follow the story<br>back to its source.','Original family scans, public downloads, saved record screenshots and oral histories. Each entry states exactly what we inspected—and what it can establish.')
content+='<div class="source-summary"><p><strong>'+str(len(sources))+'</strong> catalogue entries</p><p><strong>'+str(len(recs))+'</strong> family recording files</p><p>Research checked<br><strong>18–19 November 2026</strong></p></div>'
content+='<div class="filter-bar"><label class="search-label">Search the catalogue<input type="search" data-search="sources" placeholder="Name, record, place or reference…"></label><label>Source type<select data-filter="sources"><option value="">All types</option>'+''.join(f'<option>{esc(t)}</option>' for t in sorted(set(s['type'] for s in sources)))+'</select></label><p class="result-count" data-count="sources" aria-live="polite"></p></div><div class="sources-list" data-list="sources">'
for s in sources:
 file=s.get('file');present=file and (ROOT/'assets/documents'/file).exists()
 content+=f'<article class="source-card" id="{s["id"]}" data-item data-group="{esc(s["type"])}" data-search-text="{esc(s["title"]+" "+s["note"]+" "+(s.get("locator") or ""))}"><div class="source-id">{esc(s["id"])}</div><div><p class="eyebrow">{s["type"]}</p><h2>{s["title"]}</h2><p>{esc(s["note"])}</p>'+(f'<p class="source-locator">{esc(s["locator"])}</p>' if s.get('locator') else '')+'<div class="source-actions">'
 if s.get('url'):content+=f'<a href="{esc(s["url"])}" target="_blank" rel="noopener">Open source website</a>'
 if present:content+=f'<a href="assets/documents/{esc(file)}">View saved {"PDF" if file.endswith(".pdf") else "image"}</a><a href="assets/documents/{esc(file)}" download>Download copy</a>'
 for copy in s.get('additional',[]):
  content+=f'<a class="extra-copy" href="assets/documents/{esc(copy["file"])}">{esc(copy["label"])}</a>'
 if s['type']=='Family recording':content+=f'<a href="voices.html#{s["id"]}">Listen &amp; see passages</a>'
 content+='</div></div>'+(f'<a class="source-thumb" href="assets/documents/{esc(file)}"><img src="assets/images/{esc(s["thumb"])}" alt="Preview of {esc(s["title"])}" loading="lazy"></a>' if present and s.get('thumb') else '')+'</article>'
content+='</div><p class="empty-state" data-empty="sources" hidden>No sources match. Try a name variant or clear the type filter.</p>'
page('sources.html','Source library',content)
# Tree views: relationship style is stored separately from person status.
def graph(view,title,description,nodes,edges,width=1120,height=600):
 out=f'<section class="tree-panel" id="{view}" data-tree-panel><div class="tree-title"><h2>{title}</h2><p>{description}</p></div><div class="tree-scroll" tabindex="0" aria-label="Scrollable {esc(title)} family diagram"><svg class="family-svg" viewBox="0 0 {width} {height}" role="img" aria-labelledby="{view}-title {view}-desc"><title id="{view}-title">{title}</title><desc id="{view}-desc">{esc(description)}. Click any person for their profile. Relationship evidence is listed below the diagram.</desc>'
 coords={id:(x,y) for id,x,y,label in nodes}
 for a,b,style,label in edges:
  x,y=coords[a];xx,yy=coords[b]
  # Nodes have a fixed 182 x 84 footprint. Edges are genealogical links, not geographic paths.
  if y==yy:
   start=(x+182,y+42) if xx>x else (x,y+42); end=(xx,yy+42) if xx>x else (xx+182,yy+42)
   path=f'M{start[0]},{start[1]} L{end[0]},{end[1]}'
  else:
   path=f'M{x+91},{y+84} V{(y+84+yy)/2} H{xx+91} V{yy}'
  out+=f'<path class="edge {style}" d="{path}"><title>{esc(label)}</title></path>'
 for id,x,y,label in nodes:
  person=pd[id];parts=label.split('|')
  out+=f'<a href="people.html#{id}" aria-label="{esc(person["name"])}: open profile"><g class="tree-node" transform="translate({x},{y})"><rect width="182" height="84" rx="3"/><text x="14" y="27" class="tree-name">{esc(parts[0])}</text><text x="14" y="47" class="tree-sub">{esc(parts[1] if len(parts)>1 else person["group"])}</text><text x="14" y="68" class="tree-status">{esc(person["status"])}</text></g></a>'
 out+='</svg></div><details class="relationship-list"><summary>Read the relationships and their evidence</summary><ul>'
 for a,b,style,label in edges:out+=f'<li><a href="people.html#{a}">{esc(pd[a]["name"])}</a> / <a href="people.html#{b}">{esc(pd[b]["name"])}</a>: {esc(label)} <span class="edge-label">({{"document":"documented relationship","oral":"family testimony","inferred":"inferred / unresolved"}})</span></li>'.replace('({"document":"documented relationship","oral":"family testimony","inferred":"inferred / unresolved"})','('+{'document':'documented relationship','oral':'family testimony','inferred':'inferred / unresolved'}[style]+')')
 return out+'</ul></details></section>'
